  git('init', '-q', '.')
  git('config', 'user.email', 'code-safety@example.test')
  git('config', 'user.name', 'code-safety program')
  git('add', '-A')
  git('commit', '-qm', 'the reporting contract, the committed examiner and the locked target tree')
  git('tag', 'base')
}

/**
