input.content:
// Per-session view of a live code-safety run: runs, verdicts and directives.
import { readdirSync, readFileSync, statSync } from 'node:fs'
import { join } from 'node:path'

const root = process.argv[2]
const logs = []
const walk = (d) => {
  for (const name of readdirSync(d)) {
    const p = join(d, name)
    if (statSync(p).isDirectory()) walk(p)
    else if (name === 'session.jsonl') logs.push(p)
  }
}
walk(root)
for (const path of logs.sort()) {
  const events = readFileSync(path, 'utf8').trim().split('\n').map(l => JSON.parse(l))
  const member = events.find(e => e.type === 'program/member')
  if (member === undefined) continue
  const runs = events.filter(e => e.type === 'verification/run').map(e => `${e.data.attempt}:${e.data.verdict}`)
  const directives = events.filter(e => e.type === 'verification/directive')
  const certified = events.some(e => e.type === 'verification/certificate')
  const calls = events.filter(e => e.type === 'tool/call').length
  console.log(`${member.data.key.padEnd(14)} certified=${String(certified).padEnd(5)} calls=${String(calls).padEnd(4)} runs=[${runs.join(' ')}]`)
  for (const d of directives) console.log(`    directive: ${d.data.rootCause} | ${String(d.data.detail ?? '').split('\n').slice(0, 4).join(' / ').slice(0, 320)}`)
}

